changeSet.sql:
delete rp from role_permission rp
join permission p on p.id = rp.permission_id
where p.name in ('CREATE_COURSE', 'DELETE_COURSE');

delete from permission where name in ('CREATE_COURSE', 'DELETE_COURSE');

changeSet.rollback:
insert into permission (name) values ('CREATE_COURSE'), ('DELETE_COURSE');

insert into role_permission (role_id, permission_id)
select r.id, p.id from role r, permission p
where r.name in ('GLOBAL_ADMIN', 'EDUCATION_RESOURCE_ADMIN')
  and p.name in ('CREATE_COURSE', 'DELETE_COURSE');
